B.Jk=new A.ap([B.fj,"\u0421\u0442\u0440\u0430\u0442\u0435\u0433 \u0456\u0437 \u043f\u043b\u0430\u043d\u043e\u043c \u043d\u0430 \u0432\u0441\u0435. \u041b\u044e\u0431\u0438\u0448 \u043f\u0440\u043e\u0434\u0443\u043c\u0443\u0432\u0430\u0442\u0438 \u0441\u0438\u0441\u0442\u0435\u043c\u0438 \u043d\u0430\u043f\u0435\u0440\u0435\u0434 \u0456 \u0434\u043e\u0432\u043e\u0434\u0438\u0442\u0438 \u0441\u043a\u043b\u0430\u0434\u043d\u0456 \u0456\u0434\u0435\u0457 \u0434\u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0443.",B.fk,"\u0414\u043e\u043f\u0438\u0442\u043b\u0438\u0432\u0438\u0439 \u0432\u0438\u043d\u0430\u0445\u0456\u0434\u043d\u0438\u043a \u0456\u0434\u0435\u0439. \u0422\u043e\u0431\u0456 \u0446\u0456\u043a\u0430\u0432\u043e \u0440\u043e\u0437\u0431\u0438\u0440\u0430\u0442\u0438 \u0432\u0441\u0435 \u043d\u0430 \u0447\u0430\u0441\u0442\u0438\u043d\u0438 \u0439 \u0448\u0443\u043a\u0430\u0442\u0438, \u044f\u043a \u0432\u043e\u043d\u043e \u043f\u0440\u0430\u0446\u044e\u0454 \u043d\u0430\u0441\u043f\u0440\u0430\u0432\u0434\u0456.",B.fr,"\u041f\u0440\u0438\u0440\u043e\u0434\u0436\u0435\u043d\u0438\u0439 \u043b\u0456\u0434\u0435\u0440, \u0449\u043e \u0431\u0430\u0447\u0438\u0442\u044c \u0446\u0456\u043b\u044c \u0456 \u0432\u0435\u0434\u0435 \u0434\u043e \u043d\u0435\u0457 \u043a\u043e\u043c\u0430\u043d\u0434\u0443. \u0426\u0456\u043d\u0443\u0454\u0448 \u0435\u0444\u0435\u043a\u0442\u0438\u0432\u043d\u0456\u0441\u0442\u044c \u0456 \u0441\u043c\u0456\u043b\u0438\u0432\u0456 \u0440\u0456\u0448\u0435\u043d\u043d\u044f.",B.fs,"\u0413\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440 \u0456\u0434\u0435\u0439 \u0456 \u0441\u043c\u0456\u043b\u0438\u0432\u0438\u0445 \u0435\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0456\u0432. \u041e\u0431\u043e\u0436\u043d\u044e\u0454\u0448 \u0432\u0438\u043a\u043b\u0438\u043a\u0438, \u0441\u0443\u043f\u0435\u0440\u0435\u0447\u043a\u0438 \u0439 \u043d\u0435\u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u0456 \u043f\u0456\u0434\u0445\u043e\u0434\u0438.",B.ft,"\u0422\u0438\u0445\u0438\u0439 \u0456\u0434\u0435\u0430\u043b\u0456\u0441\u0442 \u0456\u0437 \u0432\u0435\u043b\u0438\u043a\u0438\u043c\u0438 \u0437\u0430\u0434\u0443\u043c\u0430\u043c\u0438. \u0425\u043e\u0447\u0435\u0448, \u0449\u043e\u0431 \u0442\u0432\u043e\u044f \u0440\u043e\u0431\u043e\u0442\u0430 \u043c\u0430\u043b\u0430 \u0441\u0435\u043d\u0441 \u0456 \u0434\u043e\u043f\u043e\u043c\u0430\u0433\u0430\u043b\u0430 \u043b\u044e\u0434\u044f\u043c.",B.fu,"\u041c\u0440\u0456\u0439\u043d\u0438\u043a \u0456\u0437 \u0432\u043b\u0430\u0441\u043d\u0438\u043c\u0438 \u0446\u0456\u043d\u043d\u043e\u0441\u0442\u044f\u043c\u0438. \u0428\u0443\u043a\u0430\u0454\u0448 \u0433\u0430\u0440\u043c\u043e\u043d\u0456\u044e \u0439 \u0442\u0432\u043e\u0440\u0447\u0456\u0441\u0442\u044c \u0443 \u0432\u0441\u044c\u043e\u043c\u0443, \u0449\u043e \u0440\u043e\u0431\u0438\u0448.",B.fv,"\u041d\u0430\u0442\u0445\u043d\u0435\u043d\u043d\u0438\u043a, \u044f\u043a\u0438\u0439 \u043e\u0431\u2019\u0454\u0434\u043d\u0443\u0454 \u043b\u044e\u0434\u0435\u0439. \u0423\u043c\u0456\u0454\u0448 \u043f\u0456\u0434\u0442\u0440\u0438\u043c\u0430\u0442\u0438 \u043a\u043e\u043c\u0430\u043d\u0434\u0443 \u0439 \u043f\u043e\u0432\u0435\u0441\u0442\u0438 \u0432\u0441\u0456\u0445 \u0434\u043e \u0441\u043f\u0456\u043b\u044c\u043d\u043e\u0457 \u043c\u0435\u0442\u0438.",B.fw,"\u0415\u043d\u0435\u0440\u0433\u0456\u0439\u043d\u0438\u0439 \u043f\u0435\u0440\u0448\u043e\u0432\u0456\u0434\u043a\u0440\u0438\u0432\u0430\u0447. \u0424\u043e\u043d\u0442\u0430\u043d\u0443\u0454\u0448 \u0456\u0434\u0435\u044f\u043c\u0438 \u0442\u0430 \u043b\u0435\u0433\u043a\u043e \u0437\u0430\u0445\u043e\u043f\u043b\u044e\u0454\u0448 \u0456\u043d\u0448\u0438\u0445 \u0441\u0432\u043e\u0457\u043c \u0435\u043d\u0442\u0443\u0437\u0456\u0430\u0437\u043c\u043e\u043c.",B.fx,"\u041d\u0430\u0434\u0456\u0439\u043d\u0430 \u043e\u043f\u043e\u0440\u0430 \u043a\u043e\u043c\u0430\u043d\u0434\u0438. \u0426\u0456\u043d\u0443\u0454\u0448 \u043f\u043e\u0440\u044f\u0434\u043e\u043a, \u0444\u0430\u043a\u0442\u0438 \u0439 \u0434\u043e\u0432\u0435\u0434\u0435\u043d\u0443 \u0434\u043e \u043a\u0456\u043d\u0446\u044f \u0440\u043e\u0431\u043e\u0442\u0443.",B.fy,"\u0422\u0443\u0440\u0431\u043e\u0442\u043b\u0438\u0432\u0438\u0439 \u043e\u0445\u043e\u0440\u043e\u043d\u0435\u0446\u044c \u0434\u0435\u0442\u0430\u043b\u0435\u0439. \u041f\u043e\u043c\u0456\u0447\u0430\u0454\u0448 \u0442\u0435, \u0449\u043e \u0456\u043d\u0448\u0456 \u043f\u0440\u043e\u043f\u0443\u0441\u043a\u0430\u044e\u0442\u044c, \u0456 \u0434\u0431\u0430\u0454\u0448 \u043f\u0440\u043e \u0441\u043f\u043e\u043a\u0456\u0439 \u043a\u043e\u043c\u0430\u043d\u0434\u0438.",B.fl,"\u041e\u0440\u0433\u0430\u043d\u0456\u0437\u0430\u0442\u043e\u0440, \u0449\u043e \u043b\u044e\u0431\u0438\u0442\u044c \u0447\u0456\u0442\u043a\u0456\u0441\u0442\u044c. \u0423\u043c\u0456\u0454\u0448 \u043d\u0430\u0432\u0435\u0441\u0442\u0438 \u043b\u0430\u0434 \u0456 \u0434\u043e\u0432\u0435\u0441\u0442\u0438 \u0437\u0430\u0434\u0430\u0447\u0443 \u0434\u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0443.",B.fm,"\u0414\u0443\u0448\u0430 \u043a\u043e\u043c\u0430\u043d\u0434\u0438, \u0449\u043e \u0442\u0440\u0438\u043c\u0430\u0454 \u0432\u0441\u0456\u0445 \u0440\u0430\u0437\u043e\u043c. \u0422\u043e\u0431\u0456 \u0432\u0430\u0436\u043b\u0438\u0432\u043e, \u0449\u043e\u0431 \u043b\u044e\u0434\u044f\u043c \u043f\u043e\u0440\u0443\u0447 \u0431\u0443\u043b\u043e \u0434\u043e\u0431\u0440\u0435 \u0439 \u043a\u043e\u043c\u0444\u043e\u0440\u0442\u043d\u043e.",B.fn,"\u041c\u0430\u0439\u0441\u0442\u0435\u0440-\u043f\u0440\u0430\u043a\u0442\u0438\u043a, \u0449\u043e \u0432\u0447\u0438\u0442\u044c\u0441\u044f \u0440\u0443\u043a\u0430\u043c\u0438. \u041b\u044e\u0431\u0438\u0448 \u0440\u043e\u0437\u0431\u0438\u0440\u0430\u0442\u0438\u0441\u044f, \u044f\u043a \u0443\u0441\u0435 \u0432\u043b\u0430\u0448\u0442\u043e\u0432\u0430\u043d\u043e, \u0456 \u043b\u0430\u0433\u043e\u0434\u0438\u0442\u0438 \u0446\u0435 \u0441\u0430\u043c.",B.fo,"\u0427\u0443\u0439\u043d\u0438\u0439 \u0442\u0432\u043e\u0440\u0435\u0446\u044c \u0456\u0437 \u0432\u043b\u0430\u0441\u043d\u0438\u043c \u0441\u0442\u0438\u043b\u0435\u043c. \u0426\u0456\u043d\u0443\u0454\u0448 \u0441\u0432\u043e\u0431\u043e\u0434\u0443, \u0435\u0441\u0442\u0435\u0442\u0438\u043a\u0443 \u0439 \u0449\u0438\u0440\u0456 \u0440\u0435\u0447\u0456 \u043d\u0430\u0432\u043a\u043e\u043b\u043e.",B.fp,"\u0421\u043c\u0456\u043b\u0438\u0432\u0438\u0439 \u0434\u0456\u044f\u0447, \u0449\u043e \u0436\u0438\u0432\u0435 \u043c\u043e\u043c\u0435\u043d\u0442\u043e\u043c. \u0428\u0432\u0438\u0434\u043a\u043e \u0440\u0435\u0430\u0433\u0443\u0454\u0448 \u0456 \u043d\u0435 \u0431\u043e\u0457\u0448\u0441\u044f \u0440\u0438\u0437\u0438\u043a\u0443\u0432\u0430\u0442\u0438 \u0437\u0430\u0440\u0430\u0434\u0438 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0443.",B.fq,"\u042f\u0441\u043a\u0440\u0430\u0432\u0438\u0439 \u0435\u043d\u0442\u0443\u0437\u0456\u0430\u0441\u0442, \u0449\u043e \u0437\u0430\u043f\u0430\u043b\u044e\u0454 \u0456\u043d\u0448\u0438\u0445. \u041b\u044e\u0431\u0438\u0448 \u043b\u044e\u0434\u0435\u0439, \u0440\u0443\u0445 \u0456 \u0436\u0438\u0432\u0456 \u0435\u043c\u043e\u0446\u0456\u0457 \u0432 \u0443\u0441\u044c\u043e\u043c\u0443, \u0449\u043e \u0440\u043e\u0431\u0438\u0448."],t.oi)
